#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;
    long long r = sqrtl((long double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    long long left = 1, total = 0;
    vector<pair<long long, long long>> iv;
    for (long long right = 1; right <= r; right++) {
        total += right * right;
        while (total > n) { total -= left * left; left++; }
        if (total == n) iv.push_back({left, right});
    }
    // longest first: a smaller left end means a longer sequence for a fixed sum
    stable_sort(iv.begin(), iv.end(), [](auto &a, auto &b) { return a.second - a.first > b.second - b.first; });
    string out = to_string(iv.size()) + "\n";
    for (auto &[l, rr] : iv) {
        out += to_string(rr - l + 1);
        for (long long x = l; x <= rr; x++) { out += ' '; out += to_string(x); }
        out += '\n';
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        long r = (long) Math.sqrt((double) n);
        while (r * r > n) r--;
        while ((r + 1) * (r + 1) <= n) r++;
        long left = 1, total = 0;
        List<long[]> iv = new ArrayList<>();
        for (long right = 1; right <= r; right++) {
            total += right * right;
            while (total > n) { total -= left * left; left++; }
            if (total == n) iv.add(new long[]{left, right});
        }
        iv.sort((a, b) -> Long.compare(b[1] - b[0], a[1] - a[0]));
        StringBuilder sb = new StringBuilder();
        sb.append(iv.size()).append('\n');
        for (long[] p : iv) {
            sb.append(p[1] - p[0] + 1);
            for (long x = p[0]; x <= p[1]; x++) sb.append(' ').append(x);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
)

func main() {
	var n int64
	fmt.Scan(&n)
	r := int64(math.Sqrt(float64(n)))
	for r*r > n {
		r--
	}
	for (r+1)*(r+1) <= n {
		r++
	}
	left, total := int64(1), int64(0)
	var iv [][2]int64
	for right := int64(1); right <= r; right++ {
		total += right * right
		for total > n {
			total -= left * left
			left++
		}
		if total == n {
			iv = append(iv, [2]int64{left, right})
		}
	}
	sort.SliceStable(iv, func(i, j int) bool { return iv[i][1]-iv[i][0] > iv[j][1]-iv[j][0] })
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(iv)) + "\n")
	buf := make([]byte, 0, 32)
	for _, p := range iv {
		w.WriteString(strconv.FormatInt(p[1]-p[0]+1, 10))
		for x := p[0]; x <= p[1]; x++ {
			buf = append(buf[:0], ' ')
			buf = strconv.AppendInt(buf, x, 10)
			w.Write(buf)
		}
		w.WriteByte('\n')
	}
}
